const fs=require('fs'),vm=require('vm'),assert=require('assert'),path=require('path');
const root=path.join(__dirname,'..');let src=fs.readFileSync(path.join(root,'Library.js'),'utf8');
src=src.replace('Memory cards: ', 'Memory cards: Daniel Park, Zack Lee, Mira Kim, Zoe Park');
const productionSrc=src;src=src.replace("automatic:false","automatic:true").replace("Automatic scene updates: false","Automatic scene updates: true");
const dedicatedSrc=src;src=src.replace("mode:'dedicated',player:","mode:'inline',player:");
if(process.env.DEBUG)src=src.replace('const events = new Map();','log("EVENTS",[...auto], [...contextMemories],text.slice(0,600)); const events = new Map();');
const initial=[{id:1,title:'Daniel Park',type:'character',keys:'Daniel Park,Daniel',entry:'Daniel has just transferred to J High.',description:'Keep his two-body secret hidden.'},{id:2,title:'Zoe Park',type:'character',keys:'Zoe Park,Zoe',entry:'Zoe is a student at J High.',description:'Original notes.'}];
function fresh(){return {state:{memory:{context:'DO NOT OVERWRITE',authorsNote:'AGENCY'}},storyCards:structuredClone(initial),history:[{type:'start',text:'Daniel Park waits in the courtyard at J High.'}],info:{actionCount:1,maxChars:20000,characters:[]}};}
let times=[];
function hook(c,name,text,pre=''){let env={...structuredClone(c),text,stop:false,log:(...a)=>{if(process.env.DEBUG)console.log(...a)}};
 env.addStoryCard=(keys,entry,type)=>{if(env.storyCards.some(c=>c.keys===keys))return false;env.storyCards.push({id:Math.max(0,...env.storyCards.map(c=>Number(c.id)||0))+1,keys,entry,type,title:'',description:''});const card=env.storyCards[env.storyCards.length-1];
 if(c.returnStyle==='object')return card;
 if(c.returnStyle==='id')return String(card.id);
 if(c.returnStyle==='undefined')return undefined;
 if(c.returnStyle==='true')return true;
 if(c.returnStyle==='copy')return structuredClone(card);
 return env.storyCards.length-1;};
 env.removeStoryCard=i=>env.storyCards.splice(i,1);env.updateStoryCard=(i,keys,entry,type)=>Object.assign(env.storyCards[i],{keys,entry,type});
 vm.createContext(env);const start=performance.now();const out=vm.runInContext(src+'\n'+pre+'\n'+fs.readFileSync(path.join(root,name+'.js'),'utf8'),env,{timeout:1800});times.push(performance.now()-start);
 for(const k of ['state','storyCards','history','info'])c[k]=JSON.parse(JSON.stringify(env[k]));return out;
}
function ctx(c){return hook(c,'Context','AI Instructions: Keep player agency.\nWorld Lore:\n'+c.storyCards.filter(c=>c.type==='character').map(c=>c.entry).join('\n')+'\nMemories:\n- Daniel Park met Zoe Park in the courtyard.\nRecent Story:\n'+c.history.map(x=>x.text).join('\n')+'\n[Author\'s note: Never invent player choices.]');}
function ctl(c){return c.storyCards.find(c=>c.title==='Continuity Control');}
let total=0;function test(n,fn){fn();total++;console.log('PASS',n);}
test('full isolated hook installation and preserved built-in memory',()=>{const c=fresh();hook(c,'Input','I wait.');const out=ctx(c);assert(out.text.includes('CONTINUITY GUIDANCE'));assert(c.storyCards.some(c=>/Configure\s+Inner Self/.test(c.title)));assert.deepEqual(c.state.memory,{context:'DO NOT OVERWRITE',authorsNote:'AGENCY'});assert(c.storyCards.find(x=>x.id===1).entry.includes(initial[0].entry));});
test('scene prefix verified and removed; story preserved',()=>{let c=fresh();ctx(c);assert.equal(c.state.continuityKit01.mode,'scene');const story='Daniel asks, "Which class are you in?"';const out=hook(c,'Output','<scene>'+JSON.stringify({field:'location',value:'J High courtyard',quote:'Daniel Park waits in the courtyard at J High.'})+'</scene>'+story);assert.equal(out.text,story);assert.equal(c.state.continuityKit01.scene.location.value,'J High courtyard');});
test('unsubstantiated quote and malformed JSON rejected',()=>{let c=fresh();ctx(c);hook(c,'Output','<scene>{broken}</scene>The bell rings.');assert(!c.state.continuityKit01.scene.location);assert(c.state.continuityKit01.last.includes('rejected'));ctx(c);hook(c,'Output','<scene>'+JSON.stringify({field:'location',value:'Busan',quote:'Everyone travelled to Busan yesterday.'})+'</scene>The bell rings.');assert(!c.state.continuityKit01.scene.location);});
test('player corrections cannot be overwritten',()=>{let c=fresh();ctx(c);ctl(c).entry+='\ntime: Daniel first day.\n';ctx(c);hook(c,'Output','<scene>'+JSON.stringify({field:'time',value:'Second day',quote:c.history[0].text})+'</scene>The bell rings.');assert(!c.state.continuityKit01.scene.time);assert(c.state.continuityKit01.last.includes('locked'));assert(ctx(c).text.includes('Daniel first day. [PLAYER LOCK]'));});
test('empty/missing blocks diagnosed and ordinary prose untouched',()=>{let c=fresh();ctx(c);const narrative='The task is simple, Daniel says. (He points to the classroom.)';assert.equal(hook(c,'Output',narrative).text,narrative);assert.equal(c.state.continuityKit01.misses,1);ctx(c);hook(c,'Output','<scene>{}</scene>'+narrative);assert(c.state.continuityKit01.last.includes('empty'));});
test('legacy manual present memory preserved as locks',()=>{let c=fresh();c.state.humanMemoryV2={enabled:true,records:[{kind:'present',key:'time',value:'First day.',source:'player-confirmed',status:'accepted'}]};ctx(c);assert(ctl(c).entry.includes('time: First day.'));assert.equal(c.state.humanMemoryV2.enabled,false);assert.equal(c.state.humanMemoryV2.records.length,1);});
test('context full skips additions without truncating core',()=>{let c=fresh();c.info.maxChars=300;const input='AI Instructions: '+ 'x'.repeat(270);const out=hook(c,'Context',input);assert.equal(out.text,input);assert.equal(c.state.continuityKit01.mode,'bypass');});
test('undo invalidates scene derived from removed source',()=>{let c=fresh();c.history.push({type:'continue',text:'Daniel enters the cafeteria and waits near the counter.'});ctx(c);hook(c,'Output','<scene>'+JSON.stringify({field:'location',value:'Cafeteria',quote:c.history[1].text})+'</scene>The bell rings.');c.history.pop();ctx(c);assert(!c.state.continuityKit01.scene.location);});
test('existing character gets memories without replacing lore or notes',()=>{let c=fresh();ctx(c);c.history.push({type:'continue',text:'Daniel Park turns toward the classroom door.'});c.info.actionCount++;ctx(c);const dan=c.storyCards.find(c=>c.title==='Daniel Park');assert(dan.entry.endsWith(initial[0].entry));assert(dan.description.startsWith(initial[0].description));if(process.env.DEBUG)console.log(c.storyCards,c.state.InnerSelf);assert(dan.description.includes('Daniel Park met Zoe Park'));assert.equal(c.storyCards.filter(c=>c.title==='Daniel Park').length,1);});


test('memory persists and recalls without duplicating on next hook',()=>{let c=fresh();ctx(c);c.history.push({type:'continue',text:'Daniel Park waits beside the school gate.'});c.info.actionCount++;const out=ctx(c);const dan=c.storyCards.find(x=>x.id===1);assert.equal((dan.description.match(/Daniel Park met Zoe Park/g)||[]).length,1);assert(out.text.includes('Daniel Park met Zoe Park'));});
test('card generation owns its turn and does not request scene JSON',()=>{let c=fresh();ctx(c);hook(c,'Input','Continue.','AutoCards().API.generateCard({title:"Hana",entryLimit:100});');const out=ctx(c);assert.equal(c.state.continuityKit01.mode,'cards');assert(!out.text.includes('SCENE UPDATE TASK'));for(let i=0;i<5&&!c.storyCards.some(x=>x.title==='Hana');i++){const o=hook(c,'Output','Hana studies at J High. Hana carries a blue notebook and attends the afternoon class. Hana introduced herself near the school gate. Hana agreed to meet Zoe after class to return a borrowed notebook. Hana has not met the player and does not know the player name.');c.history.push({type:'continue',text:o.text});c.info.actionCount++;if(!c.storyCards.some(x=>x.title==='Hana'))ctx(c);}if(process.env.DEBUG)console.log('GEN',c.storyCards.map(x=>x.title),c.state.AutoCards?.generation,c.state.continuityKit01);assert(c.storyCards.some(x=>x.title==='Hana'));});
function npcSetup(){let c=fresh();ctx(c);const cfg=c.storyCards.find(x=>/Configure\s+Inner Self/.test(x.title));cfg.entry=cfg.entry.replace('Enable Inner Self: false','Enable Inner Self: true').replace('Thought formation chance per turn: 25%','Thought formation chance per turn: 100%').replace('Half thought chance for Do/Say/Story: true','Half thought chance for Do/Say/Story: false');cfg.description+='\nDaniel';c.history.push({type:'continue',text:'Students walk through the hallway. '.repeat(180)+'Daniel waits at the classroom door.'});c.info.actionCount++;ctx(c);return c;}
test('optional NPC update preserves ordinary parenthetical prose',()=>{let c=npcSetup();if(process.env.DEBUG)console.log('NPC',c.state.continuityKit01);assert.equal(c.state.continuityKit01.mode,'npc');const raw='Daniel points toward the door. (The task is simple.)';const out=hook(c,'Output','(classroom_plan = `I want to find my classroom.`) '+raw);assert.equal(out.text,raw);if(process.env.DEBUG)console.log('BRAIN',c.storyCards.filter(x=>x.type==='Brain'),c.state.InnerSelf,c.state.continuityKit01);assert(c.storyCards.some(x=>x.type==='Brain'&&x.description.includes('find my classroom')));});
test('NPC core key cannot be overwritten or deleted by model',()=>{let c=npcSetup();const brain=c.storyCards.find(x=>x.type==='Brain');brain.description='core_identity: I am Daniel, a new transfer student.';hook(c,'Output','(core_identity = `I am the ruler of Seoul.`) Daniel waits.');assert(c.storyCards.find(x=>x.type==='Brain').description.includes('new transfer student'));c.history.push({type:'continue',text:'Daniel stays near the classroom door.'});c.info.actionCount++;ctx(c);hook(c,'Output','(delete core_identity) Daniel waits.');assert(c.storyCards.find(x=>x.type==='Brain').description.includes('new transfer student'));});
test('named player excluded from NPC simulation',()=>{let c=fresh();ctx(c);ctl(c).entry+='\nPlayer name: Daniel\n';const cfg=c.storyCards.find(x=>/Configure\s+Inner Self/.test(x.title));cfg.entry=cfg.entry.replace('Enable Inner Self: false','Enable Inner Self: true');cfg.description+='\nDaniel';ctx(c);assert.notEqual(c.state.continuityKit01.mode,'npc');assert(!c.storyCards.some(x=>x.type==='Brain'));});


test('large card deck and context leave core entries intact',()=>{const c=fresh();for(let i=3;i<160;i++)c.storyCards.push({id:i,title:'Location '+i,type:'location',keys:'Location '+i,entry:'Established background. '.repeat(30),description:'Creator notes.'});const before=structuredClone(c.storyCards);c.history.push({type:'continue',text:'Students walk along the corridor. '.repeat(600)+'Daniel Park waits by the door.'});c.info.maxChars=12000;const raw='AI Instructions: Player agency.\nWorld Lore: Critical canon.\nMemories:\n- Daniel Park met Zoe Park.\nRecent Story:\n'+c.history[1].text.slice(-10000)+"\n[Author's note: Keep this.]";const out=hook(c,'Context',raw);assert(out.text.length<=12000);assert(out.text.includes('Critical canon.'));assert(out.text.includes('Keep this.'));for(const old of before){const now=c.storyCards.find(x=>x.id===old.id);assert(now);assert(now.entry.endsWith(old.entry));assert(now.description.startsWith(old.description));}});
test('no dialogue claims become direct scene evidence',()=>{let c=fresh();c.history.push({type:'say',text:'I heard that Daniel Park is already in Busan.'});ctx(c);hook(c,'Output','<scene>'+JSON.stringify({field:'location',value:'Busan',quote:c.history[1].text})+'</scene>Daniel waits.');assert(!c.state.continuityKit01.scene.location);});


for(const style of ['object','id','undefined','true','copy'])test('card creation resolves '+style+' returns across hooks',()=>{const c=fresh();c.returnStyle=style;hook(c,'Input','I wait.');ctx(c);assert(ctl(c));assert(c.storyCards.some(x=>/Configure\s+Inner Self/.test(x.title)));assert(c.storyCards.some(x=>/Configure\s+Auto-Cards/.test(x.title)));hook(c,'Output','<scene>{}</scene>Daniel waits.');assert.equal(c.storyCards.filter(x=>x.title==='Continuity Control').length,1);assert.equal(c.storyCards.find(x=>x.id===1).title,'Daniel Park');});
test('repairs partial control card left by failed installation',()=>{const c=fresh();c.storyCards.push({id:3,keys:'__continuity_control_01__',title:'',entry:'',description:'',type:'Continuity'});ctx(c);assert(ctl(c).entry.includes('Scene tracking: true'));assert.equal(c.storyCards.filter(x=>x.keys==='__continuity_control_01__').length,1);});
src=dedicatedSrc;
test('dedicated extraction uses only evidence and commits multiple fields',()=>{const c=fresh();hook(c,'Input','I wait.');const out=ctx(c);assert.equal(c.state.continuityKit01.mode,'extract');assert(out.text.includes('bookkeeping-only'));assert(!out.text.includes('Before continuing the story'));const q=c.history[0].text;const r=hook(c,'Output',JSON.stringify([{field:'location',value:'J High courtyard',quote:q},{field:'present',value:'Daniel Park',quote:q}]));assert(r.text.trimStart().startsWith('[Continuity update: Saved 2'));assert.equal(c.state.continuityKit01.scene.present.value,'Daniel Park');const next=ctx(c);assert.notEqual(c.state.continuityKit01.mode,'extract');assert(next.text.includes('AI Instructions: Keep player agency.'));assert(next.text.includes('Memories:'));assert(!next.text.includes('SCENE UPDATE TASK'));});
test('failed extraction retains previous record and does not retry every turn',()=>{const c=fresh();ctx(c);c.state.continuityKit01.scene.time={value:'First day',source:'old'};const r=hook(c,'Output','Daniel smiles and walks away.');assert(r.text.includes('rejected'));assert.equal(c.state.continuityKit01.scene.time.value,'First day');ctx(c);assert.notEqual(c.state.continuityKit01.mode,'extract');});
test('explicit refresh, fenced JSON, atomic rejection and player goal guard',()=>{const c=fresh();ctx(c);hook(c,'Output','[]');hook(c,'Input','/ck refresh');ctx(c);assert.equal(c.state.continuityKit01.mode,'extract');hook(c,'Output','```json\n[]\n```');assert(c.state.continuityKit01.last.includes('No supported'));c.history.push({type:'continue',text:'You seek to maintain your status while navigating the school.'});hook(c,'Input','/ck refresh');ctx(c);hook(c,'Output',JSON.stringify([{field:'location',value:'Courtyard',quote:c.history[0].text},{field:'pending',value:'Maintain status',quote:c.history[1].text}]));assert(!c.state.continuityKit01.scene.location);assert(c.state.continuityKit01.last.includes('inner state'));});
test('dedicated refresh preserves locks and schedules automatic refresh',()=>{const c=fresh();ctx(c);ctl(c).entry+='\ntime: First day\n';hook(c,'Output',JSON.stringify([{field:'time',value:'Second day',quote:c.history[0].text}]));assert(!c.state.continuityKit01.scene.time);for(let i=0;i<8;i++){ctx(c);hook(c,'Output','Daniel waits.');}ctx(c);assert.equal(c.state.continuityKit01.mode,'extract');});
test('model quote fences and encoded arrays accepted without relaxing evidence',()=>{for(const fence of [String.fromCharCode(39).repeat(3),String.fromCharCode(34).repeat(3),'```']){const c=fresh();ctx(c);const rows=JSON.stringify([{field:'location',value:'J High courtyard',quote:c.history[0].text}]);hook(c,'Output',fence+'json\n'+rows+'\n'+fence);assert.equal(c.state.continuityKit01.scene.location.value,'J High courtyard');}const c=fresh();ctx(c);hook(c,'Output',JSON.stringify('[]'));assert(c.state.continuityKit01.last.includes('No supported'));});
test('incomplete quote fences rejected with clean one-line notice',()=>{const c=fresh();ctx(c);const r=hook(c,'Output',String.fromCharCode(34).repeat(3)+'json\n[{');assert(r.text.includes('unrecognised or incomplete update format'));assert(!r.text.includes('Unexpected token'));assert(!c.state.continuityKit01.scene.location);});
test('failed extraction retains bounded raw evidence in diagnostics',()=>{const c=fresh();const prompt=ctx(c).text;assert(prompt.includes('at most ONE'));const raw='[{"field":"location",'+ 'x'.repeat(2000);hook(c,'Output',raw);assert.equal(c.state.continuityKit01.rawSceneReplyLength,raw.length);assert.equal(c.state.continuityKit01.rawSceneReply.length,1800);assert(ctl(c).description.includes('LAST RAW SCENE RESPONSE'));assert(!c.state.continuityKit01.scene.location);});
test('plain-text update validates evidence, missing lines rejected, empty output explicit',()=>{const c=fresh();const prompt=ctx(c).text;assert(prompt.includes('three plain-text lines'));hook(c,'Output','Field: location\nValue: J High courtyard\nEvidence: '+c.history[0].text);assert.equal(c.state.continuityKit01.scene.location.value,'J High courtyard');hook(c,'Input','/ck refresh');ctx(c);hook(c,'Output','');assert(c.state.continuityKit01.last.includes('empty response'));assert.equal(c.state.continuityKit01.scene.location.value,'J High courtyard');hook(c,'Input','/ck refresh');ctx(c);hook(c,'Output','Field: location\nValue: Busan');assert.equal(c.state.continuityKit01.scene.location.value,'J High courtyard');});
test('plain-text no-change response accepted',()=>{const c=fresh();ctx(c);hook(c,'Output','No change.');assert.equal(c.state.continuityKit01.misses,0);});
test('multiple plain fields save valid evidence and skip abbreviated quote',()=>{const c=fresh();c.history.push({type:'continue',text:"You're sitting alone at a table when a tray slides onto the surface opposite you."});ctx(c);c.state.continuityKit01.scene.pending={value:'Old arm lock',source:'old'};hook(c,'Output',"Field: location\nValue: J High School cafeteria during lunch period\nEvidence: You're sitting alone at a table when a tray slides onto the surface opposite you.\nField: present\nValue: Mary Kim, Daniel Park distant, Burn Knuckles group\nEvidence: Mary Kim takes a seat... At a nearby table, you spot Daniel Park...");assert.equal(c.state.continuityKit01.scene.location.value,'J High School cafeteria during lunch period');assert(!c.state.continuityKit01.scene.present);assert(!c.state.continuityKit01.scene.pending);assert(c.state.continuityKit01.last.includes('Skipped 1'));});
src=productionSrc;
test('default and existing cards never trigger automatic scene extraction; manual refresh works',()=>{const c=fresh();hook(c,'Input','You motion Daniel to come over.');ctx(c);assert.notEqual(c.state.continuityKit01.mode,'extract');ctl(c).entry=ctl(c).entry.replace('Automatic scene updates: false\n','');for(let i=0;i<12;i++){ctx(c);assert.notEqual(c.state.continuityKit01.mode,'extract');hook(c,'Output','Daniel waits.');}hook(c,'Input','/ck refresh');ctx(c);assert.equal(c.state.continuityKit01.mode,'extract');hook(c,'Output','No change.');ctx(c);assert.notEqual(c.state.continuityKit01.mode,'extract');});
test('targeted integration archives new excerpt once without changing unrelated lore',()=>{const c=fresh();c.history.push({type:'story',text:'Zoe Park gives Ee a blue notebook near the school gate.'});ctx(c);const z=c.storyCards.find(x=>x.title==='Zoe Park');if(!z.description.includes('blue notebook'))console.log(JSON.stringify({target:c.state.ckTargeted01,diag:ctl(c).description,zoe:z}));assert(z.description.includes('blue notebook'));const before=z.description;ctx(c);assert.equal(c.storyCards.find(x=>x.title==='Zoe Park').description,before);assert(c.storyCards.find(x=>x.title==='Daniel Park').entry.includes(initial[0].entry));});
function targetedHarness(){const env={state:{},history:[],storyCards:['Mary Kim','Daniel Park','Zack Lee'].map((t,i)=>({id:i,title:t,entry:'{title: '+t+'}\nBackground.',description:'{updates: true, limit: 3200}'}))};vm.createContext(env);vm.runInContext(fs.readFileSync(path.join(root,'Targeted.js'),'utf8'),env);return env;}
test('targeted queue limits card writes, preserves backlog and drains without duplicates',()=>{const e=targetedHarness(),names=new Set(['mary kim','daniel park','zack lee']);e.history=[{type:'story',text:'Mary Kim meets Daniel Park and Zack Lee by the gate.'}];let events=e.TargetedMemory.events('',names);assert.equal([...events.values()].filter(x=>x.pendingMemories.length).length,2);for(const [t,v] of events)e.TargetedMemory.ack(t,v.pendingMemories);assert.equal(e.state.ckTargeted01.queue[0].targets.length,1);events=e.TargetedMemory.events('',names);e.TargetedMemory.ack('zack lee',events.get('zack lee').pendingMemories);assert.equal(e.state.ckTargeted01.queue.length,0);assert.equal(e.TargetedMemory.events('',names).size,0);});
test('related card only; ambiguous pronouns never force multiple character writes',()=>{const e=targetedHarness(),names=new Set(['mary kim','daniel park','zack lee']);e.history=[{type:'story',text:'Mary Kim waits beside the food stall.'}];let ev=e.TargetedMemory.events('',names);e.TargetedMemory.ack('mary kim',ev.get('mary kim').pendingMemories);e.history.push({type:'story',text:'She accepts the invitation.'});ev=e.TargetedMemory.events('',names);assert(ev.has('mary kim'));assert(!ev.has('daniel park'));e.TargetedMemory.ack('mary kim',ev.get('mary kim').pendingMemories);e.history.push({type:'story',text:'Mary Kim and Daniel Park arrive.'});ev=e.TargetedMemory.events('',names);for(const [t,v]of ev)e.TargetedMemory.ack(t,v.pendingMemories);e.history.push({type:'story',text:'She waves.'});assert.equal(e.TargetedMemory.events('',names).size,0);assert(e.state.ckTargeted01.warnings.some(w=>w.includes('Ambiguous')));});
test('queue saturation retains pending work and retries visible source later',()=>{const e=targetedHarness(),names=new Set(['mary kim']);e.state.ckTargeted01={seen:[],queue:Array.from({length:128},(_,i)=>({key:'old'+i,text:'old'+i,targets:['mary kim'],source:'old',kind:'native'})),processed:0,warnings:[],lastWindow:[],cast:[],initialized:true};e.history=[{type:'story',text:'Mary Kim opens the door.'}];e.TargetedMemory.events('',names);assert.equal(e.state.ckTargeted01.queue.length,128);assert(e.state.ckTargeted01.warnings.some(w=>w.includes('queue full')));e.TargetedMemory.ack('mary kim',['old0']);e.TargetedMemory.events('',names);assert(e.state.ckTargeted01.queue.some(j=>j.text.includes('opens the door')));});
test('disabled card excluded from writes but retains header-based recall',()=>{const e=targetedHarness(),names=new Set(['mary kim']);e.storyCards[0].description='{updates: false, limit: 3200}';e.history=[{type:'story',text:'Mary Kim opens the door.'}];const ev=e.TargetedMemory.events('World Lore: {title: Mary Kim} Existing lore.',names);assert.equal(ev.get('mary kim').pendingMemories.length,0);assert(ev.get('mary kim').titleHeader.includes('Mary Kim'));});
test('queue rollback follows failed context operation',()=>{const c=fresh();ctx(c);const saved=structuredClone(c.state.ckTargeted01);const raw='AI Instructions: Keep player agency.\nWorld Lore: Canon.\nRecent Story: Zoe Park arrives.';hook(c,'Context',raw,"InnerSelf=function(){TargetedMemory.events(text,new Set(['zoe park']));throw Error('test rollback');};");assert.deepEqual(c.state.ckTargeted01,saved);});

function refs(){const e={state:{continuityKit01:{}},history:[],storyCards:[{title:'Mary Kim',entry:'Mary has blonde hair.',description:'[CK CHANGES]Hair now cut short.[/CK CHANGES]'}]};vm.createContext(e);vm.runInContext(fs.readFileSync(path.join(root,'References.js'),'utf8'),e);return e;}
const ro={names:['mary kim'],references:true};
test('reference retrieval supplies base and separate current changes without mutation',()=>{const e=refs(),before=JSON.stringify(e.storyCards);e.history=[{text:'Mary Kim arrives.'}];const r=e.CharacterReferences.enrich('Core',ro,10000);assert(r.includes('Mary has blonde hair.'));assert(r.includes('Hair now cut short.'));assert(r.includes('not proof of presence'));assert.equal(JSON.stringify(e.storyCards),before);});
test('pronoun carry expires and scene transition clears candidate references',()=>{const e=refs();e.history=[{text:'Mary Kim arrives.'},{text:'She waves.'}];assert(e.CharacterReferences.enrich('Core',ro,10000).includes('blonde'));e.history.push({text:'The bell rings.'},{text:'Students hurry away.'});assert.equal(e.CharacterReferences.enrich('Core',ro,10000),'Core');e.history=[{text:'Mary Kim arrives.'},{text:'Next morning, the street is empty.'}];assert.equal(e.CharacterReferences.enrich('Core',ro,10000),'Core');});
test('reference budget preserves core and reports skipped character',()=>{const e=refs();e.history=[{text:'Mary Kim arrives.'}];assert.equal(e.CharacterReferences.enrich('Core',ro,5),'Core');assert(e.state.continuityKit01.references[0].includes('skipped'));});
test('existing reference not duplicated and disabled retrieval adds nothing',()=>{const e=refs();e.history=[{text:'Mary Kim arrives.'}];const core='Mary has blonde hair.';const r=e.CharacterReferences.enrich(core,ro,10000);assert.equal(r.split(core).length,2);assert(r.includes('Hair now cut short.'));assert.equal(e.CharacterReferences.enrich(core,{...ro,references:false},10000),core);});
test('duplicate first names do not select wrong reference',()=>{const e=refs();e.storyCards.push({title:'Mary Smith',entry:'Different person.'});e.history=[{text:'Mary arrives.'}];assert.equal(e.CharacterReferences.enrich('Core',{names:['mary kim','mary smith']},10000),'Core');});
test('targeted pronoun attribution stops after scene transition',()=>{const e=targetedHarness(),names=new Set(['mary kim']);e.history=[{text:'Mary Kim waits.'}];const ev=e.TargetedMemory.events('',names);e.TargetedMemory.ack('mary kim',ev.get('mary kim').pendingMemories);e.history.push({text:'Next morning, she enters a different school.'});assert.equal(e.TargetedMemory.events('',names).size,0);});
test('integration retrieves absent lore and protects player-maintained changes',()=>{const c=fresh();ctx(c);const dan=c.storyCards.find(x=>x.title==='Daniel Park');dan.description='[CK CHANGES]A bandage covers his left hand.[/CK CHANGES]\n'+dan.description;const out=hook(c,'Context','AI Instructions: Player agency.\nRecent Story: Daniel Park waits.');assert(out.text.includes('A bandage covers his left hand.'));assert(ctl(c).description.includes('CHARACTER RETRIEVAL'));assert(dan.description.includes('[CK CHANGES]'));});
function featureRefs(cards,history=[]){const e={state:{continuityKit01:{}},history,storyCards:cards};vm.createContext(e);vm.runInContext(fs.readFileSync(path.join(root,'References.js'),'utf8'),e);return e;}
const featureOpts={names:[],references:true,always:[],wordRecall:false,recallTitles:[],parentLinks:false};
test('always-include supplies up to four unique cards without a name mention',()=>{const cards=Array.from({length:5},(_,i)=>({title:'Anchor '+i,entry:'Anchor detail '+i+'.',keys:''})),e=featureRefs(cards,[{text:'An unrelated quiet scene.'}]);const out=e.CharacterReferences.enrich('Core',{...featureOpts,always:cards.map(c=>c.title)},10000);for(let i=0;i<4;i++)assert(out.includes('Anchor detail '+i));assert(!out.includes('Anchor detail 4'));});
test('supplemental budget preserves original context and enforces total and card caps',()=>{const cards=Array.from({length:4},(_,i)=>({title:'Large Anchor '+i,entry:('detail'+i+' ').repeat(900),keys:''})),e=featureRefs(cards);const core='ORIGINAL CONTEXT\n',out=e.CharacterReferences.enrich(core,{...featureOpts,always:cards.map(c=>c.title)},20000);assert(out.startsWith(core));assert(out.length-core.length<=6000);assert(out.includes('[truncated]'));const tight=e.CharacterReferences.enrich(core,{...featureOpts,always:['Large Anchor 0']},core.length+300);assert.equal(tight,core);});
test('duplicate titles and titles beyond the first 500 cards are excluded',()=>{const cards=[{title:'Duplicate',entry:'wrong one'},{title:'duplicate',entry:'wrong two'},...Array.from({length:498},(_,i)=>({title:'Filler '+i,entry:'filler'})),{title:'Beyond Limit',entry:'must not appear'}],e=featureRefs(cards);const out=e.CharacterReferences.enrich('Core',{...featureOpts,always:['Duplicate','Beyond Limit']},10000);assert.equal(out,'Core');assert(e.state.continuityKit01.references.some(x=>x.includes('duplicate title')));assert(e.state.continuityKit01.references.some(x=>x.includes('beyond 500-card index')));});
test('parent links stop on cycles, missing parents and depth two',()=>{const cards=[{title:'Root',entry:'root detail',keys:'parent=Parent One'},{title:'Parent One',entry:'parent one detail',keys:'parent=Parent Two'},{title:'Parent Two',entry:'parent two detail',keys:'parent=Too Deep'},{title:'Too Deep',entry:'too deep detail',keys:''},{title:'Cycle Root',entry:'cycle root detail',keys:'parent=Cycle Parent'},{title:'Cycle Parent',entry:'cycle parent detail',keys:'parent=Cycle Root'},{title:'Missing Root',entry:'missing root detail',keys:'parent=No Such Card'}],e=featureRefs(cards);const out=e.CharacterReferences.enrich('Core',{...featureOpts,always:['Root','Cycle Root','Missing Root'],parentLinks:true},20000);assert(out.includes('parent one detail'));assert(out.includes('parent two detail'));assert(!out.includes('too deep detail'));assert(out.includes('cycle parent detail'));assert(e.state.continuityKit01.references.some(x=>x.includes('parent cycle stopped')));assert(e.state.continuityKit01.references.some(x=>x.includes('No Such Card')));});
test('direct references outrank parents and each card is formatted once',()=>{const cards=[{title:'Root Card',entry:'root detail',keys:'parent=Direct Card'},{title:'Direct Card',entry:'direct detail',keys:''}],e=featureRefs(cards,[{text:'Direct Card enters.'}]);const out=e.CharacterReferences.enrich('Core',{...featureOpts,always:['Root Card'],names:['direct card'],parentLinks:true},10000);assert.equal((out.match(/direct detail/g)||[]).length,1);assert(e.state.continuityKit01.references.some(x=>x.startsWith('Direct Card: direct mention')));});
test('word-overlap recall rejects false positives and withholds tied candidates',()=>{const cards=[{title:'Northern Workers Second Affiliate',entry:'north detail'},{title:'Southern Workers Second Affiliate',entry:'south detail'}];let e=featureRefs(cards,[{text:'Northern Workers Second Affiliate appears.'}]);let out=e.CharacterReferences.enrich('Core',{...featureOpts,recallTitles:cards.map(c=>c.title)},10000);assert.equal(out,'Core');e=featureRefs(cards,[{text:'Workers affiliate business.'}]);out=e.CharacterReferences.enrich('Core',{...featureOpts,wordRecall:true,recallTitles:cards.map(c=>c.title)},10000);assert.equal(out,'Core');e=featureRefs(cards,[{text:'Workers second affiliate members gather.'}]);out=e.CharacterReferences.enrich('Core',{...featureOpts,wordRecall:true,recallTitles:cards.map(c=>c.title)},10000);assert.equal(out,'Core');assert(e.state.continuityKit01.references.some(x=>x.includes('tied candidates')));});
test('word-overlap recall chooses at most one fallback and clears across scene transitions',()=>{const cards=[{title:'Northern Workers Second Affiliate',entry:'north detail'},{title:'Northern Workers Second Affiliate Leadership',entry:'leadership detail'}],o={...featureOpts,wordRecall:true,recallTitles:cards.map(c=>c.title)};let e=featureRefs(cards,[{text:'Northern workers second branch members gather.'}]),out=e.CharacterReferences.enrich('Core',o,10000);assert(out.includes('north detail'));assert(!out.includes('leadership detail'));e=featureRefs(cards,[{text:'Northern workers second branch members gather.'},{text:'Next morning, the street is empty.'}]);assert.equal(e.CharacterReferences.enrich('Core',o,10000),'Core');});
test('empty recall list automatically selects up to 40 suitable unique titles',()=>{const cards=[{title:'Short Name',entry:'short detail'},{title:'Continuity Control',entry:'system detail',keys:'__continuity_control_01__'},...Array.from({length:42},(_,i)=>({title:'District Zone'+String(i).padStart(3,'0')+' School Combat Rules',entry:'auto detail '+i}))],e=featureRefs(cards,[{text:'District Zone002 school combat begins.'}]);const out=e.CharacterReferences.enrich('Core',{...featureOpts,wordRecall:true},10000);assert(out.includes('auto detail 2'));assert(!out.includes('short detail'));assert(!out.includes('system detail'));assert(e.state.continuityKit01.references.some(x=>x==='Automatic recall allowlist: 40 eligible title(s).'));});
test('new retrieval defaults are off and feature settings preserve native memory cards and hooks',()=>{const c=fresh();ctx(c);const control=ctl(c);assert(control.entry.includes('Always-include cards: '));assert(control.entry.includes('Word-overlap recall: false'));assert(control.entry.includes('Parent links: false'));control.entry=control.entry.replace('Always-include cards: ','Always-include cards: Zoe Park');const memory=structuredClone(c.state.memory),entries=c.storyCards.filter(x=>x.type==='character').map(x=>x.entry);const input=hook(c,'Input','I open the door.');assert.equal(input.text,'I open the door.');const out=hook(c,'Context','AI Instructions: Agency.\nRecent Story: An unrelated bell rings.');assert(out.text.includes('Zoe is a student at J High.'));assert.deepEqual(c.state.memory,memory);assert.deepEqual(c.storyCards.filter(x=>x.type==='character').map(x=>x.entry),entries);assert.equal(hook(c,'Output','Ordinary narrative.').text,'Ordinary narrative.');});
test('maintenance and card-generation turns receive no narrative supplemental retrieval',()=>{const saved=src;src=productionSrc;const c=fresh();ctx(c);ctl(c).entry=ctl(c).entry.replace('Always-include cards: ','Always-include cards: Zoe Park');hook(c,'Input','/ck refresh');let out=ctx(c);assert.equal(c.state.continuityKit01.mode,'extract');assert(!out.text.includes('SUPPLEMENTAL REFERENCES'));hook(c,'Output','No change.');hook(c,'Input','Continue.','AutoCards().API.generateCard({title:"Hana",entryLimit:100});');out=ctx(c);assert.equal(c.state.continuityKit01.mode,'cards');assert(!out.text.includes('SUPPLEMENTAL REFERENCES'));const n=fresh();ctx(n);ctl(n).entry=ctl(n).entry.replace('Always-include cards: ','Always-include cards: Zoe Park');const cfg=n.storyCards.find(x=>/Configure\s+Inner Self/.test(x.title));cfg.entry=cfg.entry.replace('Enable Inner Self: false','Enable Inner Self: true').replace('Thought formation chance per turn: 25%','Thought formation chance per turn: 100%').replace('Half thought chance for Do/Say/Story: true','Half thought chance for Do/Say/Story: false');cfg.description+='\nDaniel';n.history.push({type:'continue',text:'Students cross the hallway. '.repeat(180)+'Daniel waits by the door.'});n.info.actionCount++;out=ctx(n);assert.equal(n.state.continuityKit01.mode,'npc');assert(!out.text.includes('SUPPLEMENTAL REFERENCES'));src=saved;});
function canon(){const e={state:{continuityKit01:{}}};vm.createContext(e);vm.runInContext(fs.readFileSync(path.join(root,'Canon.js'),'utf8'),e);return e;}
test('canon guidance works without any deck and invents no world facts',()=>{const e=canon(),x=e.CanonConsistency.enrich('Story',{},10000);assert(x.includes('[CHARACTER CONSISTENCY]'));assert(x.includes('does not establish current presence'));assert(!x.includes('Daniel'));assert.deepEqual(Object.keys(e.state.continuityKit01),['canonStatus']);});
test('canon guidance respects context budget without truncation',()=>{const e=canon();assert.equal(e.CanonConsistency.enrich('Story',{},6),'Story');assert(e.state.continuityKit01.canonStatus.includes('Skipped'));});
test('canon guidance is optional and idempotent',()=>{const e=canon();assert.equal(e.CanonConsistency.enrich('Story',{canon:false},10000),'Story');const x=e.CanonConsistency.enrich('Story',{},10000);assert.equal(e.CanonConsistency.enrich(x,{},10000),x);});
test('integrated canon switch preserves native memory and card entries',()=>{const c=fresh();ctx(c);const before=structuredClone(c.state.memory),entries=c.storyCards.map(x=>x.entry);const out=hook(c,'Context','AI Instructions: Agency.\nRecent Story: A door opens.');assert(out.text.includes('[CHARACTER CONSISTENCY]'));assert.deepEqual(c.state.memory,before);ctl(c).entry+='\nCanon consistency: false';const off=hook(c,'Context','AI Instructions: Agency.\nRecent Story: A door opens.');assert(!off.text.includes('[CHARACTER CONSISTENCY]'));assert.equal(c.storyCards[0].entry,entries[0]);});
function arcHarness(cards){const e={state:{continuityKit01:{}},storyCards:cards};vm.createContext(e);vm.runInContext(fs.readFileSync(path.join(root,'GuidedArc.js'),'utf8'),e);return e;}
const arcOpts={arcTracking:true,arcLookahead:2,arcCards:['Milestone One','Milestone Two','Milestone Three']};
test('guided arc supplies current and one later authored card without treating either as completed',()=>{const e=arcHarness([{title:'Milestone One',entry:'The first causal event.'},{title:'Milestone Two',entry:'The second causal event.'},{title:'Milestone Three',entry:'The third causal event.'}]);const out=e.GuidedArc.enrich('CORE',arcOpts,10000);assert(out.startsWith('CORE'));assert(out.includes('CURRENT POSSIBLE MILESTONE: Milestone One'));assert(out.includes('LATER — DO NOT START EARLY: Milestone Two'));assert(!out.includes('The third causal event.'));assert(out.includes('not events that have already happened'));});
test('guided arc explicitly preserves canon when accompanying and honors material divergence',()=>{const e=arcHarness([{title:'Milestone One',entry:'A canon event.'}]);const out=e.GuidedArc.enrich('CORE',{...arcOpts,arcCards:['Milestone One'],arcLookahead:1},10000);assert(out.includes('merely accompanies or helps'));assert(out.includes('materially prevent or change a cause'));assert(out.includes('instead of undoing them to restore canon'));});
test('guided arc commands advance, mark divergence, go back, jump and reset deterministically',()=>{const e=arcHarness([{title:'Milestone One',entry:'one'},{title:'Milestone Two',entry:'two'},{title:'Milestone Three',entry:'three'}]);assert(e.GuidedArc.command('/ck arc next',arcOpts).message.includes('marked completed'));assert.equal(e.state.continuityKit01.arc.position,1);assert(e.GuidedArc.command('/ck arc altered',arcOpts).message.includes('marked altered'));assert.equal(e.state.continuityKit01.arc.position,2);e.GuidedArc.command('/ck arc back',arcOpts);assert.equal(e.state.continuityKit01.arc.position,1);e.GuidedArc.command('/ck arc goto Milestone Three',arcOpts);assert.equal(e.state.continuityKit01.arc.position,2);e.GuidedArc.command('/ck arc reset',arcOpts);assert.equal(e.state.continuityKit01.arc.position,0);assert.deepEqual(e.state.continuityKit01.arc.status,{});});
test('guided arc preserves original context at tight boundaries and caps card text',()=>{const e=arcHarness([{title:'Milestone One',entry:'x'.repeat(4000)}]),core='ORIGINAL';assert.equal(e.GuidedArc.enrich(core,{...arcOpts,arcCards:['Milestone One']},core.length+200),core);const out=e.GuidedArc.enrich(core,{...arcOpts,arcCards:['Milestone One']},10000);assert(out.startsWith(core));assert(out.length-core.length<=3800);assert(out.includes('[truncated]'));});
test('guided arc excludes duplicate and missing titles but finds configured cards late in a large deck',()=>{const cards=[{title:'Duplicate',entry:'wrong one'},{title:'duplicate',entry:'wrong two'},...Array.from({length:600},(_,i)=>({title:'Filler '+i,entry:'filler'})),{title:'Late Milestone',entry:'late but configured'}],e=arcHarness(cards);const out=e.GuidedArc.enrich('CORE',{...arcOpts,arcCards:['Duplicate','Missing','Late Milestone'],arcLookahead:3},10000);assert(out.includes('late but configured'));assert(e.state.continuityKit01.arc.diagnostics.some(x=>x.includes('duplicate title')));assert(e.state.continuityKit01.arc.diagnostics.some(x=>x.includes('exact card not found')));});
test('guided arc defaults off and input commands do not become narrative actions',()=>{const c=fresh();ctx(c);assert(ctl(c).entry.includes('Guided arc: false'));assert(!ctx(c).text.includes('[GUIDED ARC'));c.storyCards.push({id:999,title:'Milestone One',entry:'A fixed milestone.',description:'',keys:'',type:'World'});ctl(c).entry=ctl(c).entry.replace('Guided arc: false','Guided arc: true').replace('Arc cards: ','Arc cards: Milestone One');assert(ctx(c).text.includes('A fixed milestone.'));const cmd=hook(c,'Input','/ck arc next');assert.equal(cmd.stop,true);assert(cmd.text.includes('marked completed'));assert.equal(c.state.continuityKit01.arc.position,1);});
test('guided arc is withheld from scene extraction and Auto-Cards maintenance turns',()=>{const saved=src;src=productionSrc;const c=fresh();ctx(c);c.storyCards.push({id:999,title:'Milestone One',entry:'A fixed milestone.',description:'',keys:'',type:'World'});ctl(c).entry=ctl(c).entry.replace('Guided arc: false','Guided arc: true').replace('Arc cards: ','Arc cards: Milestone One');hook(c,'Input','/ck refresh');let out=ctx(c);assert.equal(c.state.continuityKit01.mode,'extract');assert(!out.text.includes('[GUIDED ARC'));hook(c,'Output','No change.');hook(c,'Input','Continue.','AutoCards().API.generateCard({title:"Hana",entryLimit:100});');out=ctx(c);assert.equal(c.state.continuityKit01.mode,'cards');assert(!out.text.includes('[GUIDED ARC'));src=saved;});
function profileHarness(){const e={state:{continuityKit01:{}}};vm.createContext(e);vm.runInContext(fs.readFileSync(path.join(root,'Profile.js'),'utf8'),e);return e;}
const profileBlock='[PLAYER PROFILE]\nName: Kai Greyrat\nOrigin: Reincarnated at birth\nMother: Zenith Greyrat\nFather: Paul Greyrat\nAncestry: Human\nConnection to Rudeus: Full sibling born one year younger\nPrimary gift: Oversized mana vessel\nSecondary gifts: Healing affinity; weaker and dormant\nStarting training: None\nAppearance: Brown hair and green eyes\nPersonality: Patient and curious\nBirth year: K408\nStarting location: Buena Village\n[/PLAYER PROFILE]';
test('player profile captures recognised creator fields and persists after opening leaves context',()=>{const e=profileHarness();assert(e.PlayerProfile.capture('Opening\n'+profileBlock));let out=e.PlayerProfile.enrich('NORMAL STORY',10000);assert(out.includes('Kai Greyrat'));assert(out.includes('Paul Greyrat'));assert(out.includes('Full sibling born one year younger'));assert(!out.includes('[PLAYER PROFILE]\nName: Kai Greyrat'));});
test('player profile guidance separates aptitude from mastery and weakens secondary gifts',()=>{const e=profileHarness();e.PlayerProfile.capture(profileBlock);const out=e.PlayerProfile.enrich('STORY',10000);assert(out.includes('potential, not unexplained mastery'));assert(out.includes('must learn skills through play'));assert(out.includes('secondary gifts begin weaker'));assert(out.includes('Starting training: None'));});
test('different player profile is ignored unless replacement is explicitly armed',()=>{const e=profileHarness();e.PlayerProfile.capture(profileBlock);const changed=profileBlock.replace('Kai Greyrat','Wrong Name');e.PlayerProfile.capture(changed);assert.equal(e.state.continuityKit01.profile.fields.Name,'Kai Greyrat');assert(e.state.continuityKit01.profile.last.includes('ignored'));e.PlayerProfile.command('/ck profile replace');e.PlayerProfile.capture(changed);assert.equal(e.state.continuityKit01.profile.fields.Name,'Wrong Name');});
test('profile clear disables accidental recapture until replace is armed',()=>{const e=profileHarness();e.PlayerProfile.capture(profileBlock);e.PlayerProfile.command('/ck profile clear');e.PlayerProfile.capture(profileBlock);assert.equal(e.state.continuityKit01.profile.captured,false);e.PlayerProfile.command('/ck profile replace');e.PlayerProfile.capture(profileBlock);assert.equal(e.state.continuityKit01.profile.captured,true);});
test('malformed or unrecognised profile blocks are rejected without inventing fields',()=>{const e=profileHarness();assert.equal(e.PlayerProfile.capture('[PLAYER PROFILE]\nFavorite color: Blue\nPower: Infinite\n[/PLAYER PROFILE]'),null);assert.equal(e.state.continuityKit01.profile.captured,false);assert(e.state.continuityKit01.profile.last.includes('rejected'));});
test('profile budget preserves original context exactly when guidance cannot fit',()=>{const e=profileHarness(),core='ORIGINAL CONTEXT';e.PlayerProfile.capture(profileBlock);assert.equal(e.PlayerProfile.enrich(core,core.length+50),core);assert(e.state.continuityKit01.profile.last.includes('insufficient context'));});
test('integrated profile commands stop generation and diagnostics show saved values',()=>{const c=fresh(),raw='AI Instructions: Agency.\n'+profileBlock+'\nRecent Story: A cradle rocks.';let out=hook(c,'Context',raw);assert(out.text.includes('PLAYER PROFILE RULES'));assert.equal(c.state.continuityKit01.profile.fields.Father,'Paul Greyrat');assert(ctl(c).description.includes('Kai Greyrat'));const status=hook(c,'Input','/ck profile status');assert.equal(status.stop,true);assert(status.text.includes('Saved profile'));});
test('saved profile is withheld from extraction and Auto-Cards maintenance turns',()=>{const saved=src;src=productionSrc;const c=fresh();hook(c,'Context','AI Instructions: Agency.\n'+profileBlock+'\nRecent Story: A cradle rocks.');hook(c,'Input','/ck refresh');let out=ctx(c);assert.equal(c.state.continuityKit01.mode,'extract');assert(!out.text.includes('PLAYER PROFILE RULES'));assert(!out.text.includes('ESTABLISHED PLAYER PROFILE'));hook(c,'Output','No change.');hook(c,'Input','Continue.','AutoCards().API.generateCard({title:"Hana",entryLimit:100});');out=ctx(c);assert.equal(c.state.continuityKit01.mode,'cards');assert(!out.text.includes('PLAYER PROFILE RULES'));assert(!out.text.includes('ESTABLISHED PLAYER PROFILE'));src=saved;});
test('family lookup integrates with hooks and preserves cards and native memory',()=>{const saved=src;try{src=productionSrc;const c=fresh();c.storyCards.push({id:900,title:'Paul Greyrat',entry:'UNIQUE_FATHER_REFERENCE',keys:'Paul',type:'character',description:'original'});hook(c,'Context',profileBlock+'\nRecent Story: A cradle rocks.');const before=structuredClone(c.state.memory);hook(c,'Input','I ask my dad about childhood.');const out=hook(c,'Context','Recent Story: A quiet room.');assert(out.text.includes('UNIQUE_FATHER_REFERENCE'));assert.deepEqual(c.state.memory,before);assert.equal(c.storyCards.find(x=>x.id===900).entry,'UNIQUE_FATHER_REFERENCE');hook(c,'Output','He answers.');assert(!hook(c,'Context','Recent Story: A quiet room.').text.includes('UNIQUE_FATHER_REFERENCE'));}finally{src=saved;}});
test('family request is withheld from Auto-Cards maintenance and cleared afterwards',()=>{const saved=src;try{src=productionSrc;const c=fresh();c.storyCards.push({id:900,title:'Paul Greyrat',entry:'UNIQUE_FATHER_REFERENCE',keys:'Paul',type:'character',description:''});hook(c,'Context',profileBlock+'\nRecent Story: A cradle rocks.');hook(c,'Input','I ask my dad about childhood.','AutoCards().API.generateCard({title:"Hana",entryLimit:100});');const out=hook(c,'Context','Recent Story: A quiet room.');assert.equal(c.state.continuityKit01.mode,'cards');assert(!out.text.includes('SUPPLEMENTAL REFERENCES'));hook(c,'Output','Hana is a student.');assert.equal(c.state.continuityKit01.familyRequest,null);}finally{src=saved;}});
test('clarification integrates without permanent relationship writes and clears after output',()=>{const saved=src;try{src=productionSrc;const c=fresh();hook(c,'Input','Do you remember my brother?');const out=hook(c,'Context','Recent Story: We are talking.');assert(out.text.includes('REFERENCE CLARIFICATION'));assert(!c.state.continuityKit01.profile?.fields?.Brother);hook(c,'Output','What is his name?');assert.equal(c.state.continuityKit01.mentionRequest,null);assert(!hook(c,'Context','Recent Story: We are talking.').text.includes('REFERENCE CLARIFICATION'));}finally{src=saved;}});
test('clarification withheld during card maintenance',()=>{const saved=src;try{src=productionSrc;const c=fresh();hook(c,'Input','Do you remember my brother?','AutoCards().API.generateCard({title:"Hana",entryLimit:100});');const out=ctx(c);assert.equal(c.state.continuityKit01.mode,'cards');assert(!out.text.includes('REFERENCE CLARIFICATION'));hook(c,'Output','Hana is a student.');assert.equal(c.state.continuityKit01.mentionRequest,null);}finally{src=saved;}});
test('paired presentation quotes accepted in dedicated evidence without altering raw diagnostics',()=>{const saved=src;try{src=productionSrc;for(const [a,b] of [['"','"'],["'","'"],['“','”'],['‘','’'],['«','»']]){const c=fresh();hook(c,'Input','/ck refresh');ctx(c);const raw='Field: location\nValue: J High courtyard\nEvidence: '+a+c.history[0].text+b;hook(c,'Output',raw);assert.equal(c.state.continuityKit01.scene.location.value,'J High courtyard');assert.equal(c.state.continuityKit01.rawSceneReply,raw);assert.equal(c.state.continuityKit01.misses,0);}}finally{src=saved;}});
test('paraphrased mismatched short and whitespace-altered evidence still rejected',()=>{const saved=src;try{src=productionSrc;for(const q of ['"Daniel Park stands in the courtyard at J High."','“Daniel Park waits in the courtyard at J High."','"Daniel  Park waits in the courtyard at J High."','"courtyard"','" Daniel Park waits in the courtyard at J High. "']){const c=fresh();hook(c,'Input','/ck refresh');ctx(c);hook(c,'Output','Field: location\nValue: Wrong location\nEvidence: '+q);assert(!c.state.continuityKit01.scene.location,q);assert.equal(c.state.continuityKit01.misses,1);}}finally{src=saved;}});
test('original quoted source and internal quotation marks remain exact',()=>{const saved=src;try{src=productionSrc;const c=fresh();c.history=[{type:'story',text:'The room has a sign reading "Main Hall" on its door.'}];hook(c,'Input','/ck refresh');ctx(c);hook(c,'Output','Field: location\nValue: Main Hall doorway\nEvidence: “'+c.history[0].text+'”');assert.equal(c.state.continuityKit01.scene.location.value,'Main Hall doorway');}finally{src=saved;}});
test('quoted evidence respects player locks',()=>{const saved=src;try{src=productionSrc;const c=fresh();ctx(c);ctl(c).entry+='\nlocation: Locked room';hook(c,'Input','/ck refresh');ctx(c);hook(c,'Output','Field: location\nValue: Courtyard\nEvidence: "'+c.history[0].text+'"');assert(!c.state.continuityKit01.scene.location);assert(c.state.continuityKit01.last.includes('player-locked'));}finally{src=saved;}});
test('inline evidence tolerates paired wrappers too',()=>{const saved=src;try{src=dedicatedSrc.replace("mode:'dedicated',player:","mode:'inline',player:");const c=fresh();ctx(c);assert.equal(c.state.continuityKit01.mode,'scene');const out=hook(c,'Output','<scene>'+JSON.stringify({field:'location',value:'J High courtyard',quote:'“'+c.history[0].text+'”'})+'</scene>Daniel waits.');assert.equal(c.state.continuityKit01.scene.location.value,'J High courtyard');assert.equal(out.text,'Daniel waits.');}finally{src=saved;}});
test('event tracker integrates normal output review and shared recall',()=>{const saved=src;try{src=productionSrc;const c=fresh();hook(c,'Input','I watch Daniel Park.');ctx(c);const out=hook(c,'Output','Daniel Park defeated Zack Lee in the courtyard.');assert(!out.text.includes('CK EVENT NOTICE'));assert.equal(c.state.continuityKit01.events.records[0].status,'pending');const review=hook(c,'Input','/memory confirm 1');assert(!review.stop);hook(c,'Input','I ask Daniel Park about the fight.');const next=ctx(c);assert(next.text.includes('CONFIRMED EVENT MEMORY'));assert(!next.text.includes('CK EVENT NOTICE'));}finally{src=saved;}});
test('maintenance outputs do not become events or reminder turns',()=>{const saved=src;try{src=productionSrc;const c=fresh();hook(c,'Input','/ck refresh');ctx(c);hook(c,'Output','No change.');assert.equal(c.state.continuityKit01.events.ticks,0);hook(c,'Input','Continue.','AutoCards().API.generateCard({title:"Hana",entryLimit:100});');ctx(c);hook(c,'Output','Daniel Park defeated Zack Lee in the courtyard.');assert.equal(c.state.continuityKit01.events.records.length,0);assert.equal(c.state.continuityKit01.events.ticks,0);}finally{src=saved;}});
test('timeline integrates control switch and suppresses guided arc duplicate',()=>{const saved=src;try{src=productionSrc;const c=fresh();hook(c,'Input','I wait.');ctl(c).entry+='\nTimeline helper: true\nEvent tracking: false\nGuided arc: true\nArc cards: Daniel Park\n';c.storyCards.push({"id":990,"title":"Fixture","type":"World","keys":"__test_event__","description":"","entry":"[CANON EVENT]\n{\"schema\":1,\"id\":\"test-school\",\"title\":\"Test school\",\"calendar\":\"K\",\"years\":[422,422],\"cues\":[\"enrollment\"],\"locations\":[\"Sharia\"],\"participants\":[],\"prerequisites\":[],\"changes\":[],\"summary\":\"A fictional test enrollment.\",\"source\":\"Test fixture\",\"certainty\":\"uncertain\"}\n[/CANON EVENT]"});c.history.push({type:'continue',text:'Current year: K422. Sharia.'});const out=ctx(c);assert(out.text.includes('CANON TIMELINE REFERENCE'));assert(!out.text.includes('[GUIDED ARC'));assert(ctl(c).description.includes('CANON TIMELINE'));assert(!hook(c,'Output','Daniel Park defeated Zack Lee.').text.includes('CK EVENT NOTICE'));}finally{src=saved;}});
test('timeline withheld from dedicated maintenance turn',()=>{const saved=src;try{src=productionSrc;const c=fresh();hook(c,'Input','I wait.');ctl(c).entry+='\nTimeline helper: true\n';c.storyCards.push({"id":990,"title":"Fixture","type":"World","keys":"__test_event__","description":"","entry":"[CANON EVENT]\n{\"schema\":1,\"id\":\"test-school\",\"title\":\"Test school\",\"calendar\":\"K\",\"years\":[422,422],\"cues\":[\"enrollment\"],\"locations\":[\"Sharia\"],\"participants\":[],\"prerequisites\":[],\"changes\":[],\"summary\":\"A fictional test enrollment.\",\"source\":\"Test fixture\",\"certainty\":\"uncertain\"}\n[/CANON EVENT]"});c.history.push({type:'continue',text:'Current year: K422. Sharia.'});hook(c,'Input','/ck refresh');assert(!ctx(c).text.includes('CANON TIMELINE REFERENCE'));}finally{src=saved;}});
test('player card is created from profile with stable and dynamic sections and is always supplied',()=>{const saved=src;try{src=productionSrc;const c=fresh(),raw='AI Instructions: Agency.\n'+profileBlock+'\nRecent Story: A cradle rocks.';const out=hook(c,'Context',raw),pc=c.storyCards.find(x=>x.keys==='__ck_player_character__');assert(pc);assert.equal(pc.title,'PLAYER — Kai Greyrat');assert(pc.entry.includes('Stable profile'));assert(pc.entry.includes('Primary gift: Oversized mana vessel'));assert(pc.entry.includes('Dynamic starting state'));assert(pc.entry.includes('Starting training: None'));assert(out.text.includes(pc.entry));assert(c.storyCards.some(x=>x.keys==='__ck_player_character_review__'));const later=hook(c,'Context','AI Instructions: Agency.\nRecent Story: Years pass.');assert(later.text.includes('[PLAYER CHARACTER — AUTHORITATIVE]'));assert(later.text.includes('Kai Greyrat'));}finally{src=saved;}});
test('detected player changes remain pending until confirmed through review card',()=>{const saved=src;try{src=productionSrc;const c=fresh();hook(c,'Context',profileBlock+'\nRecent Story: Training begins.');hook(c,'Output','Kai Greyrat learned the Water Arrow technique after completing the lesson.');let pc=c.storyCards.find(x=>x.keys==='__ck_player_character__'),review=c.storyCards.find(x=>x.keys==='__ck_player_character_review__');assert(!pc.entry.includes('Water Arrow'));assert(review.description.includes('Water Arrow'));review.entry='Request: confirm 1';hook(c,'Input','Continue.');pc=c.storyCards.find(x=>x.keys==='__ck_player_character__');assert(pc.entry.includes('[ability] Kai Greyrat learned the Water Arrow technique'));assert.equal(c.state.continuityKit01.playerCharacter.candidates[0].status,'confirmed');}finally{src=saved;}});
test('player review correction replacement and removal are explicit and deterministic',()=>{const saved=src;try{src=productionSrc;const c=fresh();hook(c,'Context',profileBlock+'\nRecent Story: Training begins.');const review=()=>c.storyCards.find(x=>x.keys==='__ck_player_character_review__');review().entry='Request: add equipment Kai carries a bronze practice sword.';hook(c,'Input','Continue.');assert(c.storyCards.find(x=>x.keys==='__ck_player_character__').entry.includes('#1 [equipment] Kai carries a bronze practice sword.'));review().entry='Request: replace 1 Kai carries a reforged silver practice sword.';hook(c,'Input','Continue.');let entry=c.storyCards.find(x=>x.keys==='__ck_player_character__').entry;assert(!entry.includes('bronze practice sword'));assert(entry.includes('#2 [equipment] Kai carries a reforged silver practice sword.'));review().entry='Request: remove 2';hook(c,'Input','Continue.');entry=c.storyCards.find(x=>x.keys==='__ck_player_character__').entry;assert(!entry.includes('reforged silver'));}finally{src=saved;}});
test('quoted hypothetical changes and maintenance outputs never update player review',()=>{const saved=src;try{src=productionSrc;const c=fresh();hook(c,'Context',profileBlock+'\nRecent Story: Training begins.');hook(c,'Output','Roxy said, "Kai Greyrat learned teleportation."');assert.equal(c.state.continuityKit01.playerCharacter.candidates.length,0);hook(c,'Input','Continue.','AutoCards().API.generateCard({title:"Hana",entryLimit:100});');hook(c,'Context','Recent Story: Training continues.');hook(c,'Output','Kai Greyrat mastered forbidden teleportation and gained a crown.');assert.equal(c.state.continuityKit01.playerCharacter.candidates.length,0);}finally{src=saved;}});
test('generic player-named cards are excluded from retrieval and authoritative card survives card maintenance',()=>{const saved=src;try{src=productionSrc;const c=fresh();c.storyCards.push({id:901,title:'Kai Greyrat',entry:'CONFLICTING_GENERIC_PLAYER_CARD',description:'Auto-generated.',keys:'Kai',type:'Character'});hook(c,'Context',profileBlock+'\nRecent Story: A cradle rocks.');hook(c,'Input','I remember Kai Greyrat.');let out=hook(c,'Context','AI Instructions: Agency.\nRecent Story: A quiet room.');assert(out.text.includes('[PLAYER CHARACTER — AUTHORITATIVE]'));assert(!out.text.includes('CONFLICTING_GENERIC_PLAYER_CARD'));const before=c.storyCards.find(x=>x.keys==='__ck_player_character__').entry;hook(c,'Input','Continue.','AutoCards().API.generateCard({title:"Hana",entryLimit:100});');hook(c,'Context','Recent Story: A quiet room.');hook(c,'Output','Hana is a student with a blue notebook and a quiet voice.');assert.equal(c.storyCards.find(x=>x.keys==='__ck_player_character__').entry,before);}finally{src=saved;}});
test('player card context budget fails closed without truncating original context',()=>{const saved=src;try{src=productionSrc;const c=fresh();c.info.maxChars=600;const raw=profileBlock+'\nRecent Story: '+'.'.repeat(300);const out=hook(c,'Context',raw);assert.equal(out.text.includes('[PLAYER CHARACTER — AUTHORITATIVE]'),false);assert(out.text.includes(profileBlock));assert(c.storyCards.some(x=>x.keys==='__ck_player_character__'));}finally{src=saved;}});
console.log(total+' tests passed; max hook '+Math.max(...times).toFixed(1)+'ms');
